class Component extends DCLogic {
  constructor(props) {
    super(props);
    const a = 2 + Math.floor(Math.random() * 7);
    const b = 2 + Math.floor(Math.random() * 7);
    this.state = { video: false, a: a, b: b, nearEnd: false };
  }
  componentWillUnmount() { window.removeEventListener('scroll', this._endScroll); window.removeEventListener('resize', this._endScroll); }

  componentDidMount() {
    document.documentElement.lang = 'en-US';
    // Near-end gate (same rule as the accepted Mobile view): hide the fixed chat widget so footer legal links stay visible/operable at true document end.
    this._endScroll = () => {
      const nearEnd = (window.scrollY + window.innerHeight) > (document.documentElement.scrollHeight - 260);
      if (nearEnd !== this.state.nearEnd) this.setState({ nearEnd });
    };
    window.addEventListener('scroll', this._endScroll, { passive: true });
    window.addEventListener('resize', this._endScroll);
    this._endScroll();
    // Live semantics: attribution fields are populated from the landing URL, not server-injected here.
    try {
      const p = new URLSearchParams(window.location.search);
      const form = document.querySelector('form[action*="submitContactForm"]');
      if (!form) return;
      const set = (n, v) => { const el = form.querySelector('[name="' + n + '"]'); if (el) el.value = v; };
      set('lead_source_url', window.location.href);
      ['utm_source', 'utm_medium', 'utm_campaign', 'utm_keyword', 'utm_content'].forEach(k => set(k, p.get(k) || ''));
    } catch (e) {}
  }

  focusSourceLink(n) { const el = document.querySelector('[data-source-media="video"]'); if (el) { el.focus(); return; } if ((n || 0) < 20) setTimeout(() => this.focusSourceLink((n || 0) + 1), 30); }

  renderVals() {
    const a = this.state.a, b = this.state.b;
    const _ne = this.state.nearEnd;
    return {
      wO: _ne ? 0 : 1, wV: _ne ? 'hidden' : 'visible', wP: _ne ? 'none' : 'auto',
      yearNow: new Date().getFullYear(),
      heritageYears: new Date().getFullYear() - 1908,
      arithLabel: 'How much is ' + a + ' + ' + b + ' ?',
      videoOn: this.state.video,
      videoOff: !this.state.video,
      posterOpacity: 1,
      playVideo: () => { this.setState({ video: true }); this.focusSourceLink(0); },
      validate: (e) => {
        const f = e.currentTarget;
        const given = parseInt((f.querySelector('[name="result"]') || {}).value, 10);
        if (given !== a + b) {
          e.preventDefault();
          window.alert('Please check the sum: how much is ' + a + ' + ' + b + ' ?');
        }
      }
    };
  }
}
